#!/usr/bin/env node
/**
 * Writes src/data/robotRenders.ts from the files under public/robots/: one entry per render, keyed
 * by the `Exercise.demo` value it belongs to (`<diagram-slug>` for public/robots/<slug>.webp,
 * `cat:<slug>` for public/robots/cat/<slug>.webp). Run by hand after adding or removing a render;
 * the renders and the generated file are committed together, never built in CI, never fetched at
 * runtime (src/data/robotRenders.test.ts holds the two in step).
 *
 * The renders themselves were made once, off the device, from free-exercise-db photographs
 * (Unlicense) with an image model: a faceless satin-metal robot in the photo's pose, lit white
 * on black. The accent glow is CSS (`.ember-glow`), so a new accent needs no new render.
 *
 * Usage: node scripts/robot-renders.mjs
 */
import { readdirSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const DIR = fileURLToPath(new URL('../public/robots/', import.meta.url));
const OUT = fileURLToPath(new URL('../src/data/robotRenders.ts', import.meta.url));
const webp = (dir) => readdirSync(dir).filter((f) => f.endsWith('.webp')).map((f) => f.slice(0, -5));
const keys = [...webp(DIR), ...webp(DIR + 'cat/').map((s) => `cat:${s}`)].sort();

writeFileSync(
  OUT,
  `/* AUTO-GENERATED by scripts/robot-renders.mjs — edit that script, not this file. */

/** Every \`Exercise.demo\` key that has a robot render bundled under public/robots/. */
export const ROBOT_RENDER_KEYS: readonly string[] = ${JSON.stringify(keys, null, 2).replace(/"/g, "'")};
`,
);
console.log(`Wrote ${OUT} (${keys.length} renders).`);
